hunks.after:
v_policy_effective_from date;
v_approval_contract public.contracts%rowtype; v_approval_before jsonb; v_approval_after jsonb;
v_approval_capture jsonb; v_approval_key text; v_approval_response jsonb;
v_approval_changes jsonb:='[]'::jsonb;

-- R242: derive the fixed key inside the same actual settings owner.
-- No approval field is admitted from Office. The just-saved dated target
-- membership and native configured AGENCY scope own apply/clear together.
-- All ordinary manager email/domain policy bytes are preserved.
if private.weekly_source_configured_agency_invoice_v1(v_client,v_group_id,v_agency,v_environment,v_effective_from)
  is distinct from v_client_agency_basis then
  raise exception 'WEEKLY_SOURCE_AGENCY_FIXED_APPROVAL_SCOPE_STALE' using errcode='40001';end if;
for v_approval_contract in
  select contract.* from public.contracts contract where contract.client_id=v_client
    and ((v_client_agency_basis and contract.weekly_timesheet_source::text='HEALTHROSTER'
      and contract.end_date>=v_effective_from)
      or (not v_client_agency_basis and contract.candidate_manager_approval_policy_json->'approval'='"NOT_REQUIRED"'::jsonb))
  order by contract.id for update
loop
  v_approval_before:=v_approval_contract.candidate_manager_approval_policy_json;
  v_approval_after:=case when v_client_agency_basis
    then coalesce(v_approval_before,'{}'::jsonb)||jsonb_build_object('approval','NOT_REQUIRED')
    else v_approval_before-'approval' end;
  if v_approval_after is not distinct from v_approval_before then continue;end if;
  v_approval_capture:=jsonb_build_object('schema_version','WEEKLY_SOURCE_AGENCY_FIXED_APPROVAL_CHANGE_V1',
    'contract_id',v_approval_contract.id,'client_id',v_client,'source_group_id',v_group_id,
    'previous_source_group_id',v_old_group_id,'effective_from',v_effective_from,
    'expected_contract_updated_at',v_approval_contract.updated_at,
    'before_policy',v_approval_before,'after_policy',v_approval_after,
    'operation',case when v_client_agency_basis then 'APPLY' else 'CLEAR' end);
  -- Every real change has a new native receipt, including A -> B -> A in
  -- one transaction. An equal historical input hash is not a replay owner.
  -- Feature request replay is already owned by its immutable feature receipt;
  -- a repeated Client save with unchanged policy takes the no-op above.
  v_approval_capture:=v_approval_capture||jsonb_build_object('input_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_AGENCY_FIXED_APPROVAL_CHANGE_V1',v_approval_capture),'hex'));
  v_approval_key:='SOURCE_AGENCY_FIXED:'||gen_random_uuid()::text;
  update public.contracts set candidate_manager_approval_policy_json=v_approval_after,
    updated_at=transaction_timestamp() where id=v_approval_contract.id returning * into v_approval_contract;
  v_approval_response:=public.contract_manager_authoriser_policy_get_v1(v_approval_contract.id)
    ||jsonb_build_object('system_fixed_approval',v_approval_capture,'idempotent_replay',false);
  insert into public.candidate_manager_authoriser_policy_receipts(
    entity_kind,entity_id,idempotency_key,semantic_sha256,response_json,actor_user_id,recorded_at_utc)
  values('CONTRACT',v_approval_contract.id,v_approval_key,
    extensions.digest(convert_to(v_approval_after::text,'UTF8'),'sha256'),v_approval_response,v_actor,transaction_timestamp());
  v_approval_changes:=v_approval_changes||jsonb_build_array(v_approval_capture||jsonb_build_object(
    'contract_updated_at',v_approval_contract.updated_at,'receipt_idempotency_key',v_approval_key));
end loop;

if v_old_group_id is not null and v_old_group_id<>v_group_id then
  perform private._weekly_source_settings_stale_open_v1(v_old_group_id,v_client);

return private._weekly_source_settings_client_shape_v1(
  v_agency,v_environment,v_client,v_effective_from
)||case when jsonb_array_length(v_approval_changes)=0 then '{}'::jsonb
  else jsonb_build_object('contract_approval_changes',v_approval_changes) end;
